-- 0028 · PC-56 TENANT-SW-d · the AGM pack's words that leave the console: the DATASET name (the 6e-2 ready notice says "Your {{dataset}}
-- export is ready") and each section METHOD in en / hi / gu. The PDF is drawn by the 13d text writer (WinAnsi Helvetica) and cannot carry
-- Hindi or Gujarati script — so the pack's dataset file carries the method in the pack's second language from HERE (`agm.method.<item>`),
-- next to the English method printed in the PDF. Static sentences (no figures): the figures travel in their own column.
INSERT INTO ui_messages (key, language_code, text) VALUES
 ('exports.dataset.governance.agm_pack', 'en', 'AGM pack'),
 ('exports.dataset.governance.agm_pack', 'hi', 'वार्षिक आम सभा (AGM) पैक'),
 ('exports.dataset.governance.agm_pack', 'gu', 'વાર્ષિક સામાન્ય સભા (AGM) પેક'),

 ('agm.method.gmv', 'en', 'GMV = the goods value (order subtotal, before delivery, fees and tax) of every order completed in the financial year. Orders refunded or cancelled after completion are not counted. Source: orders.'),
 ('agm.method.gmv', 'hi', 'GMV = वित्त वर्ष में पूरे हुए हर ऑर्डर का माल मूल्य (ऑर्डर उप-योग, डिलीवरी, शुल्क और कर से पहले)। पूरा होने के बाद रिफ़ंड या रद्द हुए ऑर्डर नहीं गिने जाते। स्रोत: ऑर्डर।'),
 ('agm.method.gmv', 'gu', 'GMV = નાણાકીય વર્ષમાં પૂર્ણ થયેલા દરેક ઓર્ડરનું માલ મૂલ્ય (ઓર્ડર પેટા-સરવાળો, ડિલિવરી, ફી અને કર પહેલાં). પૂર્ણ થયા પછી રિફંડ કે રદ થયેલા ઓર્ડર ગણાતા નથી. સ્રોત: ઓર્ડર.'),
 ('agm.method.paid_to_members', 'en', 'Paid to members = the net of the ledger legs posted to members'' Main wallets under escrow_release in the year: order settlements are credits, dispute and return claw-backs are debits. Source: the ledger.'),
 ('agm.method.paid_to_members', 'hi', 'सदस्यों को भुगतान = वर्ष में escrow_release के तहत सदस्यों के मुख्य वॉलेट में दर्ज लेजर प्रविष्टियों का शुद्ध योग: ऑर्डर निपटान जमा हैं, विवाद और वापसी की वसूली नामे हैं। स्रोत: लेजर।'),
 ('agm.method.paid_to_members', 'gu', 'સભ્યોને ચુકવણી = વર્ષમાં escrow_release હેઠળ સભ્યોના મુખ્ય વૉલેટમાં નોંધાયેલી લેજર એન્ટ્રીઓનો ચોખ્ખો સરવાળો: ઓર્ડર પતાવટ જમા છે, વિવાદ અને પરત વસૂલાત ઉધાર છે. સ્રોત: લેજર.'),
 ('agm.method.paid_share', 'en', 'Share = Paid to members divided by GMV, both shown, in the same currency (basis points, rounded down). A ratio of two facts.'),
 ('agm.method.paid_share', 'hi', 'हिस्सा = सदस्यों को भुगतान ÷ GMV, दोनों दिखाए गए, एक ही मुद्रा में (बेसिस पॉइंट, नीचे की ओर पूर्णांकित)। दो तथ्यों का अनुपात।'),
 ('agm.method.paid_share', 'gu', 'હિસ્સો = સભ્યોને ચુકવણી ÷ GMV, બંને દર્શાવેલ, એક જ ચલણમાં (બેસિસ પોઇન્ટ, નીચે તરફ પૂર્ણાંકિત). બે તથ્યોનો ગુણોત્તર.'),
 ('agm.method.platform_fees', 'en', 'Platform fees = the net posted to the platform Fees account by this cooperative''s order settlements and claw-backs in the year. Source: the ledger.'),
 ('agm.method.platform_fees', 'hi', 'प्लेटफ़ॉर्म शुल्क = वर्ष में इस समिति के ऑर्डर निपटान और वसूली से प्लेटफ़ॉर्म शुल्क खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।'),
 ('agm.method.platform_fees', 'gu', 'પ્લેટફોર્મ ફી = વર્ષમાં આ મંડળીના ઓર્ડર પતાવટ અને વસૂલાતથી પ્લેટફોર્મ ફી ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.'),
 ('agm.method.gst_on_commission', 'en', 'GST on commission = the net posted to the platform GST-payable account by this cooperative''s order settlements in the year. Source: the ledger.'),
 ('agm.method.gst_on_commission', 'hi', 'कमीशन पर GST = वर्ष में इस समिति के ऑर्डर निपटान से प्लेटफ़ॉर्म GST-देय खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।'),
 ('agm.method.gst_on_commission', 'gu', 'કમિશન પર GST = વર્ષમાં આ મંડળીના ઓર્ડર પતાવટથી પ્લેટફોર્મ GST-ચૂકવવાપાત્ર ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.'),
 ('agm.method.tenant_commission', 'en', 'Cooperative commission = the net posted to this cooperative''s own Commission account by its order settlements in the year. Source: the ledger.'),
 ('agm.method.tenant_commission', 'hi', 'समिति कमीशन = वर्ष में ऑर्डर निपटान से इस समिति के अपने कमीशन खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।'),
 ('agm.method.tenant_commission', 'gu', 'મંડળી કમિશન = વર્ષમાં ઓર્ડર પતાવટથી આ મંડળીના પોતાના કમિશન ખાતામાં નોંધાયેલી ચોખ્ખી રકમ. સ્રોત: લેજર.'),
 ('agm.method.surplus', 'en', 'FPO surplus is refused: the platform keeps no ledger of the cooperative''s operating costs, so a surplus cannot be computed from facts. See the audited accounts.'),
 ('agm.method.surplus', 'hi', 'FPO अधिशेष नहीं दिया गया: प्लेटफ़ॉर्म समिति के परिचालन खर्च का कोई लेजर नहीं रखता, इसलिए तथ्यों से अधिशेष नहीं निकाला जा सकता। लेखा-परीक्षित खाते देखें।'),
 ('agm.method.surplus', 'gu', 'FPO પૂરાંત આપવામાં આવી નથી: પ્લેટફોર્મ મંડળીના સંચાલન ખર્ચનું કોઈ લેજર રાખતું નથી, તેથી તથ્યોમાંથી પૂરાંત ગણી શકાતી નથી. ઓડિટ થયેલા હિસાબ જુઓ.'),
 ('agm.method.operating_costs', 'en', 'Operating costs are refused: no cost ledger exists on the platform. The cooperative''s own books (and its auditor) are the source.'),
 ('agm.method.operating_costs', 'hi', 'परिचालन खर्च नहीं दिया गया: प्लेटफ़ॉर्म पर कोई खर्च लेजर नहीं है। समिति की अपनी बहियाँ (और उसके लेखा परीक्षक) स्रोत हैं।'),
 ('agm.method.operating_costs', 'gu', 'સંચાલન ખર્ચ આપવામાં આવ્યો નથી: પ્લેટફોર્મ પર કોઈ ખર્ચ લેજર નથી. મંડળીના પોતાના ચોપડા (અને તેના ઓડિટર) સ્રોત છે.'),
 ('agm.method.statements', 'en', 'Settlement statements whose period overlaps the financial year, issued to members. Each member reads their own on the statements page.'),
 ('agm.method.statements', 'hi', 'वित्त वर्ष से मेल खाती अवधि के निपटान विवरण, जो सदस्यों को जारी हुए। हर सदस्य विवरण पेज पर अपना पढ़ता है।'),
 ('agm.method.statements', 'gu', 'નાણાકીય વર્ષ સાથે મેળ ખાતા સમયગાળાના પતાવટ પત્રકો, જે સભ્યોને આપવામાં આવ્યા. દરેક સભ્ય પત્રક પેજ પર પોતાનું વાંચે છે.'),
 ('agm.method.snapshot', 'en', 'The share register as of the year end: rows that existed then and have not changed since. If any changed, the extract is refused — the register keeps no history.'),
 ('agm.method.snapshot', 'hi', 'वर्ष के अंत पर शेयर रजिस्टर: उस समय मौजूद और उसके बाद न बदली पंक्तियाँ। कोई बदली हो तो अंश नहीं दिया जाता — रजिस्टर इतिहास नहीं रखता।'),
 ('agm.method.snapshot', 'gu', 'વર્ષના અંતે શેર રજિસ્ટર: ત્યારે હાજર અને ત્યાર પછી ન બદલાયેલી પંક્તિઓ. કોઈ બદલાઈ હોય તો અંશ આપવામાં આવતો નથી — રજિસ્ટર ઇતિહાસ રાખતું નથી.'),
 ('agm.method.closed_in_fy', 'en', 'Resolutions closed in the financial year, with the outcome recorded at close (quorum and majority as recorded then).'),
 ('agm.method.closed_in_fy', 'hi', 'वित्त वर्ष में बंद हुए प्रस्ताव, बंद होते समय दर्ज परिणाम के साथ (उस समय दर्ज कोरम और बहुमत)।'),
 ('agm.method.closed_in_fy', 'gu', 'નાણાકીય વર્ષમાં બંધ થયેલા ઠરાવો, બંધ થતી વખતે નોંધાયેલા પરિણામ સાથે (ત્યારે નોંધાયેલ કોરમ અને બહુમતી).'),
 ('agm.method.annexure', 'en', 'The auditor''s report as uploaded by the cooperative — not produced or checked by the platform.'),
 ('agm.method.annexure', 'hi', 'लेखा परीक्षक की रिपोर्ट, जैसी समिति ने अपलोड की — प्लेटफ़ॉर्म द्वारा न बनाई गई, न जाँची गई।'),
 ('agm.method.annexure', 'gu', 'ઓડિટરનો અહેવાલ, જેમ મંડળીએ અપલોડ કર્યો — પ્લેટફોર્મે બનાવ્યો કે તપાસ્યો નથી.'),
 ('agm.method.quorum', 'en', 'Quorum as recorded in the setting governance.quorum_bp (the cooperative''s own, or the platform default when it has none).'),
 ('agm.method.quorum', 'hi', 'कोरम, जैसा governance.quorum_bp सेटिंग में दर्ज है (समिति का अपना, या न होने पर प्लेटफ़ॉर्म का डिफ़ॉल्ट)।'),
 ('agm.method.quorum', 'gu', 'કોરમ, જેમ governance.quorum_bp સેટિંગમાં નોંધાયેલું છે (મંડળીનું પોતાનું, અથવા ન હોય તો પ્લેટફોર્મનું ડિફોલ્ટ).'),
 ('agm.method.notice_period', 'en', 'The AGM notice period is refused: no bylaw setting for it exists on the platform, and a number from memory is not data.'),
 ('agm.method.notice_period', 'hi', 'AGM सूचना अवधि नहीं दी गई: प्लेटफ़ॉर्म पर इसकी कोई उपनियम सेटिंग नहीं है, और याद से लिखी संख्या डेटा नहीं है।'),
 ('agm.method.notice_period', 'gu', 'AGM નોટિસ સમયગાળો આપવામાં આવ્યો નથી: પ્લેટફોર્મ પર તેનું કોઈ પેટાનિયમ સેટિંગ નથી, અને યાદથી લખેલી સંખ્યા ડેટા નથી.')
ON CONFLICT (key, language_code) DO UPDATE SET text = EXCLUDED.text;
